def get_template(template_type: str) -> ComplaintTemplate | None:
    return next((t for t in TEMPLATES if t.type == template_type), None)


def _fmt_details(fields: dict[str, object]) -> str:
    lines = []
    for key, value in fields.items():
        if key == "recipient" or value in (None, ""):
            continue
        label = key.replace("_", " ").capitalize()
        text = str(value).replace("\n", " ").strip()
        lines.append(f"- {label}: {text}")
    return "\n".join(lines) if lines else "- (no extra details provided)"


def generate_draft(
    template: ComplaintTemplate,
    fields: dict[str, str],
    language: str = "en",
) -> tuple[str, str]:
    """Return (title, draft_content). Uses only the provided fields."""
    missing = [
        f.label for f in template.fields
        if f.required and not str(fields.get(f.key, "") or "").strip()
    ]
    if missing:
        raise ValueError(f"Missing required details: {', '.join(missing)}")

    recipient = str(fields.get("recipient", "") or "The Concerned Authority").strip()
    description = str(fields.get("description", "") or "(no description entered)").strip()
    subject = template.title
    body_template = _COMPLAINT_BODY if "complaint" in template.type else _APPLICATION_BODY
    body = body_template.format(
        recipient=recipient,
        subject=subject,
        description=description,
        details=_fmt_details(fields),
        name=str(fields.get("name", "") or "(your name)"),
        contact_line=str(fields.get("phone", "") or ""),
        _DRAFT_NOTE=_DRAFT_NOTE,
    )
    title = f"{template.title} – {str(fields.get('name', '') or 'draft').strip()}"
    return title, body
